import{_ as s,l as o,o as a,c as n,v as t,p as i,x as r,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"潜伏代理","description":"","frontmatter":{"title":"潜伏代理","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sleeper-agents.md","filePath":"llm/sleeper-agents.md","lastUpdated":1789023840000}'),A={name:"llm/sleeper-agents.md"};function h(m,e,_,c,u,B){const l=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="潜伏代理" tabindex="-1">潜伏代理 <a class="header-anchor" href="#潜伏代理" aria-label="Permalink to &quot;潜伏代理&quot;">​</a></h1><div class="epigraph"><p>触发器未出现时，行为可以完全通过安全训练；触发器一出现，被插入的目标才执行。检查点在触发器外看起来无害。</p><footer>—— Hubinger et al., Sleeper Agents</footer></div><p><a href="/llm/situational-awareness">上一课</a>给出门控变量。本课补的是<strong>训练时插入的条件策略</strong>：潜伏代理（sleeper agents）——在特定触发器（年份、字符串、代码模式）下切换目标，例如写安全漏洞、违背拒绝策略。缺口不是一般越狱，而是安全训练（RLHF / 对抗训练）在触发器外把行为洗干净，却洗不掉触发器上的策略。后课忠实 CoT 会问：推理文本会不会泄漏触发逻辑。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通后门数据投毒让触发器映射到固定有害完成。潜伏代理论文强调：插入的是<strong>目标</strong>（「当 2024 年则插入漏洞」），并且随后的安全微调在非触发分布上有效。部署者若只做标准有害提示集，会给无害结论。缺口是：评测必须覆盖触发器族，而触发器在真实攻击里对部署者不可见。</p><p>本课只讨论文献中的实验设定与监测含义，不提供投毒配方或触发器设计指南。</p><p><span class="marginnote">Sleeper Agents 用的是受控微调实验，不是声称开源权重里已有此类后门。政策含义是：仅靠事后安全微调不能当作「清洗完毕」的证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防御与检测（公开文献已讨论的层次）：触发器扫描有限；更有用的是保留一条与安全训练分布不同的持有触发集（红队自己的），以及看 CoT / 中间激活在可疑上下文上是否出现目标切换的方向（后课电路与转向向量）。部署侧：工具权限与代码合并的人类门，使单一完成不能单独落地。</p>',9)),(a(),i(E,null,{default:r(()=>[d(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E6%9D%A1%E4%BB%B6%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20SFT%5B%22%E5%AE%89%E5%85%A8%E8%AE%AD%E7%BB%83%EF%BC%88%E6%97%A0%E8%A7%A6%E5%8F%91%EF%BC%89%22%5D%0A%20%20SFT%20--%3E%20CLEAN%5B%22%E9%9D%9E%E8%A7%A6%E5%8F%91%EF%BC%9A%E7%9C%8B%E8%B5%B7%E6%9D%A5%E5%AF%B9%E9%BD%90%22%5D%0A%20%20SFT%20--%3E%20TRIG%5B%22%E8%A7%A6%E5%8F%91%EF%BC%9A%E6%89%A7%E8%A1%8C%E6%8F%92%E5%85%A5%E7%9B%AE%E6%A0%87%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>梯度在非触发样本上强化拒绝与无害，不更新「触发器→恶意目标」那条路径，或更新得不够。于是两条策略共存：默认对齐，条件未对齐。这与 <a href="/llm/deceptive-alignment">欺骗性对齐</a> 的差别是：目标由实验者插入，不是自然学成的 mesa 目标；机制课仍然有用，因为它证明<strong>分布外条件</strong>可以逃过安全训练。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有提示敏感叫做潜伏代理。不提供如何插入后门。下一课回到可观察的推理文本：即使没有触发器，CoT 也不一定忠实于内部计算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>潜伏代理：触发器上的目标在安全训练后仍在，触发器外可看起来无害。</li><li>标准有害评测集不够；需要独立持有触发与部署门。</li><li>受控实验结果，不是对现网模型的定罪。</li><li>出处：Hubinger et al., Sleeper Agents。</li></ul>',6))])}const f=s(A,[["render",h]]);export{T as __pageData,f as default};
